// Flag any account the Python /reconciliation-check service reports as mismatched.
// The HTTP node already sent {account_id, ledger_sum, reported_balance} and received
// back {account_id, mismatch, difference} — filter on the service's verdict.
return items.filter(i => i.json.mismatch === true);

// Rule: if scheduled date falls on weekend/holiday, process EARLY (previous business day)
// so payees are never left waiting. Mark item with adjusted_run flag for audit.
return items.map(i => {
  const d = new Date(i.json.next_run_date);
  const day = d.getDay();
  i.json.is_weekend_or_holiday = (day === 0 || day === 6);
  return i;
});

// Safeguard: discard any retrieved match with score < 0.75 so Pinecone
// never lets a superficially-similar-but-wrong past case leak into drafting.
return items.filter(i => (i.json.score || 0) >= 0.75);

parameters.text:
You are a banking support assistant. Using ONLY the policy context and account history provided, draft a reply. Cite the policy_id you used. If the context does not contain a clear answer, respond with exactly: NO_CONFIDENT_ANSWER — do not guess or invent policy.

Customer email: {{$json.text}}
Account context: {{$json.accountContext}}
Policy context: {{$json.policyContext}}

parameters.jsCode:
// Force human path if: no policy_id cited, response == NO_CONFIDENT_ANSWER,
// intent is FRAUD_DISPUTE/JOINT_ACCOUNT, or account is on_hold.
const text = $json.output || '';
const needsHuman = text.includes('NO_CONFIDENT_ANSWER') || !/policy_id/i.test(text) || $json.intent === 'FRAUD_DISPUTE' || $json.intent === 'JOINT_ACCOUNT' || $json.on_hold === true;
return [{ json: { ...$json, needsHuman } }];

// 2 holders -> mutual consent means BOTH must approve (threshold = total_other_holders)
// 3+ holders -> majority vote means threshold = floor(total_other_holders/2) + 1
const totalOther = $json.holder_count - 1;
const threshold = $json.holder_count <= 2 ? totalOther : Math.floor(totalOther / 2) + 1;
return [{ json: { ...$json, votes_required: threshold } }];

// Hard gate: if autonomy_rules says requires_human=true for this action,
// this node throws unless the request carries an authenticated ops user id.
if ($json.requires_human && !$json.ops_user_id) {
  throw new Error('Blocked by autonomy rule: fraud_hold_release requires a human ops actor.');
}
return items;

if ($json.requires_human && !$json.approver_user_id) {
  throw new Error('Blocked by autonomy rule: rag_reply_send requires a human approver.');
}
return items;

// Reads the customer's reply email body for APPROVE / DECLINE and
// matches the thread's request_id (parsed from a hidden reference tag
// n8n inserted in the original outbound email) so we know which
// pending transfer this reply resolves.
const body = ($json.text || '').toUpperCase();
return [{ json: { ...$json, approved: body.includes('APPROVE') && !body.includes('DECLINE') } }];

// Each reply increments inputs_received; the calling flow's account_id
// / dispute_id is recovered from the email thread reference tag.
return [{ json: { ...$json, input_text: $json.text, inputs_received: ($json.inputs_received || 0) + 1 } }];

// Customer's reply is a claim only — it queues ops review, it never
// releases the hold by itself (matches the false-positive decision:
// self-attestation triggers human review, it does not auto-release).
return [{ json: { ...$json, customer_claims_legitimate: true } }];

// Collapse the retrieved policy chunks + the account pull + the original
// email into the single { text, accountContext, policyContext } shape the
// grounded drafting prompt actually needs. Nothing upstream built these
// fields before -- the prompt was referencing empty values.
const policyContext = items.length
  ? items.map(i => `[${(i.json.metadata && i.json.metadata.policy_id) || 'UNKNOWN'}] ${i.json.pageContent || ''}`).join('\n\n')
  : 'NO_MATCHING_POLICY_FOUND';

const emailItem = $('Gmail Trigger: New Support Email').first().json;
const accountRows = $('PG: Pull Account + History').all().map(i => i.json);

let accountContext = 'No account record found.';
if (accountRows.length > 0) {
  const acc = accountRows[0];
  const recentTx = accountRows
    .filter(r => r.created_at)
    .slice(0, 5)
    .map(r => `${r.created_at}: ${r.type} ${r.amount}`)
    .join('; ');
  accountContext = `Account ${acc.account_id}, balance ${acc.balance}, on_hold=${acc.on_hold}. Recent transactions: ${recentTx || 'none'}.`;
}

return [{
  json: {
    text: emailItem.text,
    accountContext,
    policyContext
  }
}];

// One-time seed content for the Pinecone policy index.
// These are placeholder bank policies written for this capstone project --
// there were no real policy documents to ingest, so this Code node stands in
// for a document source. If real policy docs exist later, replace this node
// with one that reads them (e.g. from Google Drive or Postgres) and keep the
// rest of this branch (Doc Loader -> Embeddings -> Pinecone insert) as-is.
const policies = [{"policy_id": "POL-001", "title": "Card Decline & Insufficient Funds", "text": "A card or transfer is declined whenever the requested amount exceeds the account's available balance (balance minus any on_hold amount). The system never allows a transaction that would push balance below zero except for the explicit debt-tracking flow used for reversals and chargebacks. When a decline happens, the customer must be told the specific reason (insufficient funds vs. account on hold vs. frozen) rather than a generic failure message, so they know what action to take next."}, {"policy_id": "POL-002", "title": "Fraud Hold & False-Positive Resolution", "text": "Any transaction scoring above the fraud threshold triggers an automatic hold on the account (on_hold = true) without waiting for human review, because delaying a hold is riskier than a false alarm. The hold itself may be placed unsupervised. However, releasing a hold always requires a human ops decision \u2014 automation is never allowed to release its own hold, even if the customer replies claiming the transaction is legitimate. A customer's self-attestation reply is logged for ops review, not treated as proof of innocence."}, {"policy_id": "POL-003", "title": "Joint Account Authority & Dispute", "text": "Two-holder joint accounts default to either-or authority: either holder may transact alone unless both-signature mode was explicitly configured, which requires the other holder's email approval before a transfer executes. Accounts with three or more holders use majority-vote authority for holder-management actions (adding, removing a holder, or closing the account). Any single holder may open a dispute on a joint account; if the dispute concerns shared funds, all holders must provide input before it is finalized \u2014 one holder cannot unilaterally resolve a dispute affecting the others."}, {"policy_id": "POL-004", "title": "Standing Order Failure & Retry", "text": "Standing orders due on a weekend or bank holiday are shifted to the prior business day, never delayed to after the due date. If a standing order fails due to insufficient funds, it is automatically retried the next day, up to three attempts total. After the third consecutive failure the order is marked permanently failed and the customer is notified by email \u2014 this notification does not require human sign-off since no funds have moved and there is no risk in sending it automatically."}, {"policy_id": "POL-005", "title": "Chargeback & Reversal Debt", "text": "When a transfer's second leg fails after the first leg already succeeded (for example, a debit succeeds but the matching credit fails), the first leg is explicitly reversed before the transaction is rolled back, so the customer never loses funds to a partial failure. When a chargeback or reversal creates a negative balance because funds were already spent, this is recorded as a distinct debt-type transaction with an attached repayment plan \u2014 never silently deducted from a future deposit. All reversal and chargeback processing requires human sign-off before the repayment plan is sent to the customer."}, {"policy_id": "POL-006", "title": "Account Closure & Holder Removal", "text": "A joint account can only close when every holder agrees; if even one holder disagrees, the account is frozen rather than closed, and all holders are notified of the disagreement. Removing a single holder from a two-holder account requires mutual consent from both parties. On accounts with three or more holders, removing a holder requires a majority vote among the remaining holders, tallied only after every holder has had the chance to respond."}, {"policy_id": "POL-007", "title": "Minor & Guardian Accounts", "text": "A minor account holder can only view account activity \u2014 they cannot initiate transfers or manage the account. A linked guardian may perform write actions (transfers, standing orders, holder management) on the minor's behalf. Any write attempt made directly by a minor is rejected and logged to the audit trail rather than silently ignored, so there is a record of the attempt. Thirty days before a minor holder's 18th birthday, the guardian receives an advance-notice email; on the birthday itself the account automatically converts to full access and both parties are notified."}, {"policy_id": "POL-008", "title": "General Support & Escalation", "text": "For any customer support request that does not clearly match a known policy \u2014 including ambiguous complaints, questions outside the scope of documented rules, or requests where account context is insufficient to give a confident answer \u2014 support responses must not guess. If there is no policy that clearly covers the situation, the correct response is to escalate to a human agent rather than invent an answer, since an incorrect but confident-sounding reply causes more harm than a short delay for human review."}];
return policies.map(p => ({ json: p }));
